// ---------------------------------------------------------------------------
const Module = z.object({
    index: z.number().int().min(1),
    title: z.string(),
    summary: z.string(),
    learning_objectives: z.array(z.string()).optional().default([]),
    artifact: z.string().optional().default(""),
    duration_min: z.number().int(),
});

const CoursePublish = z.object({
    event: z.literal("course.publish"),
    signal_id: z.string().uuid(),
    published_at: z.string(),
    course: z.object({
        slug: z.string().min(1),
        title: z.string().min(1),
        category: z.string(),
        summary: z.string().optional().default(""),
        price_usd: z.number().nullable().optional(),
        lead_magnet: z
            .object({
                title: z.string().optional().default(""),
                description: z.string().optional().default(""),
                slug: z.string().nullable().optional(),
                url: z.string().url().nullable().optional(),
            })
            .optional()
            .default({ title: "", description: "" }),
        cta: z.object({
            headline: z.string().optional().default(""),
            subtext: z.string().optional().default(""),
            free_url: z.string().url().nullable().optional(),
            paid_url: z.string().url(),
        }),
        syllabus: z.object({ modules: z.array(Module) }),
        demand: z.object({
            registration_count: z.number().int(),
            priority_score: z.number().int().min(0).max(100),
            source_url: z.string().url().nullable().optional(),
        }),
    }),
});

type CoursePublishPayload = z.infer<typeof CoursePublish>;

// ---------------------------------------------------------------------------
// 2) Signature verification — HMAC-SHA256 of the raw request body using the
//    shared secret. Header format: `sha256=<64-char hex>`.
//    Constant-time compare via crypto.timingSafeEqual.
// ---------------------------------------------------------------------------
function verifySignature(rawBody: string, header: string | null): boolean {
    const secret = process.env.LEARNFORGE_WEBHOOK_SECRET;
    if (!secret) return true; // signing disabled — accept all
    if (!header) return false;

    const provided = header.startsWith("sha256=") ? header.slice(7) : header;
    const expected = crypto
        .createHmac("sha256", secret)
        .update(rawBody)
        .digest("hex");

    if (provided.length !== expected.length) return false;
    try {
        return crypto.timingSafeEqual(
            Buffer.from(provided, "hex"),
            Buffer.from(expected, "hex"),
        );
    } catch {
        return false;
    }
}

