// ---------------------------------------------------------------------------
// 4) Route handler.
// ---------------------------------------------------------------------------
export async function POST(req: NextRequest) {
    // Read raw body first — HMAC must be computed over the byte-identical
    // payload the Radar signed. Don't call req.json() before this.
    const rawBody = await req.text();

    if (!verifySignature(rawBody, req.headers.get("x-radar-signature"))) {
        return NextResponse.json(
            { ok: false, error: "bad signature" },
            { status: 401 },
        );
    }

    let body: unknown;
    try {
        body = JSON.parse(rawBody);
    } catch {
        return NextResponse.json(
            { ok: false, error: "invalid json" },
            { status: 400 },
        );
    }

    const parsed = CoursePublish.safeParse(body);
    if (!parsed.success) {
        return NextResponse.json(
            {
                ok: false,
                error: "invalid payload",
                issues: parsed.error.issues,
            },
            { status: 422 },
        );
    }

    try {
        const courseRow = await upsertCourse(parsed.data);
        return NextResponse.json(
            {
                ok: true,
                course_id: courseRow.id,
                slug: courseRow.slug,
                signal_id: parsed.data.signal_id,
            },
            { status: 200 },
        );
    } catch (err) {
        const msg = err instanceof Error ? err.message : "unknown error";
        console.error("[radar] upsert failed:", msg);
        return NextResponse.json(
            { ok: false, error: "upsert failed", detail: msg },
            { status: 500 },
        );
    }
}

// Health-check ping so a GET to the same URL returns 200 (useful for
// uptime monitors). Radar only ever POSTs.
export async function GET() {
    return NextResponse.json({
        ok: true,
        service: "learnforge-course-publish",
        version: "v1",
    });
}

export const runtime = "nodejs"; // crypto.timingSafeEqual requires Node runtime
export const dynamic = "force-dynamic"; // never cache mutations
